  const tabs = c2.real ? COLLECTIVE_TABS : c2.brought ? COLLECTIVE_TABS.filter((t) => t.key === "act" || t.key === "sign") : [{ key: "act", label: "Act" }, { key: "members", label: "Members, money and endings" }];
