  const input = o.media === "text" ? '<label>The text to seal (opened by each buyer once paid)</label><textarea name="text" rows="5"></textarea>' : `<label>${o.media === "picture" ? "The picture: a JPEG file" : o.media === "video" ? "The film: an MP4 file (the video Module)" : "The recording: an M4A file (the audio Module)"}</label><input type="file" name="file" accept="${o.media === "picture" ? "image/jpeg" : o.media === "video" ? ".mp4,video/mp4" : ".m4a,audio/mp4"}">${o.media === "picture" ? "" : `<p class="k-small k-soft">Checked by the ${o.media === "video" ? "video" : "audio"} Module, then stripped to the ${o.media === "video" ? "film" : "sound"} alone before anything is sealed: every ${o.media === "video" ? "frame" : "sample"} byte for byte; titles, dates, places and covers removed.</p>`}`;
